package config;
import static org.junit.jupiter.api.Assertions.*;import java.util.Map;import org.junit.jupiter.api.Test;
class ConfiguracionMercadoPagoRetornoTest {@Test void separaWebhookYRetornoWeb(){var c=ConfiguracionMercadoPago.desde(Map.of("MP_ENABLED","true","MP_ACCESS_TOKEN","APP_USR-test","MP_WEBHOOK_SECRET","secret","MP_PUBLIC_BASE_URL","https://api.example","MP_RETURN_BASE_URL","http://localhost:4321","MP_ENVIRONMENT","sandbox","MP_TEST_USER_ID","123"));assertEquals("api.example",c.webhookUrl().getHost());assertEquals("localhost",c.retornoExitoso().getHost());assertEquals(4321,c.retornoExitoso().getPort());assertTrue(c.retornoExitoso().toString().contains("pago=aprobado"));}@Test void retornoExternoExigeHttps(){assertThrows(IllegalStateException.class,()->ConfiguracionMercadoPago.desde(Map.of("MP_ENABLED","true","MP_ACCESS_TOKEN","APP_USR-test","MP_WEBHOOK_SECRET","secret","MP_PUBLIC_BASE_URL","https://api.example","MP_RETURN_BASE_URL","http://web.example","MP_ENVIRONMENT","sandbox","MP_TEST_USER_ID","123")));}}